
function matchHeight($o, m) {
    $o.css("height", "auto");
    for (var foo_length = $o.length, i = 0; i < Math.ceil(foo_length / m); i++) {
      for (var maxHeight = 0, j = 0; j < m; j++) $o.eq(i * m + j).height() > maxHeight && (maxHeight = $o.eq(i * m + j).height());
      for (var k = 0; k < m; k++) $o.eq(i * m + k).height(maxHeight)
    }
  }
  
  function matchHeightS($o, m) {
    var _w = Math.floor(100 / m * 10) / 10,
      _parent = $o.parent();
    if (m > 1) {
      $o.css("height", "auto"), "none" != $o.css("float") ? $o.css("width", String(_w) + "%") : "flex" == _parent.css("display") && $o.css("width", String(_w) + "%");
      for (var foo_length = $o.length, i = 0; i < Math.ceil(foo_length / m); i++) {
        for (var maxHeight = 0, j = 0; j < m; j++) $o.eq(i * m + j).height() > maxHeight && (maxHeight = $o.eq(i * m + j).height());
        for (var k = 0; k < m; k++) $o.eq(i * m + k).height(maxHeight)
      }
    } else $o.css("height", "auto"), "none" != $o.css("float") ? $o.css("width", String(_w) + "%") : "flex" == _parent.css("display") && $o.css("width", String(_w) + "%")
  }


